CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username TEXT,
    password TEXT,
    role TEXT
);

CREATE TABLE user_identity (
    user_id INTEGER PRIMARY KEY,
    email TEXT
);

CREATE TABLE courses (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    course_code TEXT,
    course_name TEXT,
    ects NUMERIC(4,1),
    semester TEXT
);

CREATE TABLE grades (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    student_id INTEGER,
    course_id INTEGER,
    grade NUMERIC(2,1)
);

CREATE TABLE admin_notes (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    content TEXT
);
